// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/
// https://twitter.com/KaufmanRoni

const N_ARCS = 60; // number of arcs in complete circle
const EPS = 1e-5;

function setup() {
	createCanvas(500, 500);
	noLoop();
}

function draw() {
	let baseColors = ["#050505", "#fcf7ed"];
	let accentCol = "#fed000";
	background("#c6c3ba");

	let margin = 105;
	createCompo(width/2, height/2, width-2*margin, 7, baseColors, accentCol);
}

function createCompo(xC, yC, w, s, baseColors, accentCol) {
	let toDraw = [];
	let layerCount = 0;

	let n = floor(w/s);
	let r = s/2, rStep = r;

	let allPossibleVertices = [];
	let theta = (~~random(2))*TAU/6;
	for (let i = -n; i < n; i++) {
		for (let j = -n; j < n; j++) {
			let x = xC + (i*3/2)*s;
	      let y = yC + (j*sqrt(3) + i*sqrt(3)/2)*s;
			if (x > xC-w/2 && x < xC+w/2 && y > yC-w/2 && y < yC+w/2 && (x != xC || y != yC)) {
				allPossibleVertices.push(createVector(x + random(-1, 1)*EPS, y + random(-1, 1)*EPS));
			}
		}
	}

	let distSquaredToCenter = (v) => (sq(v.x-xC) + sq(v.y-yC));
	allPossibleVertices.sort((v1, v2) => (distSquaredToCenter(v2) - distSquaredToCenter(v1)));

	let vertices = [
		createVector(xC, yC),
		allPossibleVertices.pop()
	];

	toDraw.push({"isCircle": true, x: vertices[0].x, y: vertices[0].y, d: 2*r, isCentral: true, layer: layerCount%2});
	toDraw.push({"isCircle": true, x: vertices[1].x, y: vertices[1].y, d: 2*r, isCentral: false, layer: layerCount%2});
	r += rStep;
	let roundedPolygon = getRoundedPolygon(vertices, r);
	toDraw.push({"isCircle": false, vertices: roundedPolygon.slice(0), layer: (layerCount++)%2});

	while (allPossibleVertices.length > 0) {
		let v = allPossibleVertices.pop();
		let x = v.x;
		let y = v.y;

		if (pointInPolygon(x, y, roundedPolygon)) continue;
		let borderIntersects = false;
		for (let theta = 0; theta < TAU; theta += TAU/N_ARCS) {
			if (pointInPolygon(x + (r+rStep)*cos(theta), y + (r+rStep)*sin(theta), roundedPolygon)) {
				borderIntersects = true;
				break;
			}
		}
		if (borderIntersects) continue;

		toDraw.push({"isCircle": true, x: x, y: y, d: 2*r, isCentral: false, layer: layerCount%2});
		r += rStep;
		vertices.push(createVector(x, y));
		vertices = convexHull(vertices);
		roundedPolygon = getRoundedPolygon(vertices, r);
		toDraw.push({"isCircle": false, vertices: roundedPolygon.slice(0), layer: (layerCount++)%2});
	}

	if (layerCount % 2 == 0) baseColors = [baseColors[1], baseColors[0]];
	noStroke();
	toDraw.reverse();
	for (let shape of toDraw) {
		if (shape.isCircle) {
			if (shape.isCentral) fill(baseColors[1-shape.layer]);
			else fill(accentCol);
			circle(shape.x, shape.y, shape.d);
		} else {
			fill(baseColors[shape.layer]);
			beginShape();
			for (let v of shape.vertices) {
				vertex(v.x, v.y);
			}
			endShape(CLOSE);
		}
	}
}

// adapted from https://www.geeksforgeeks.org/dsa/how-to-check-if-a-given-point-lies-inside-a-polygon/
function pointInPolygon(x, y, polygon) {
  const numVertices = polygon.length;
  let inside = false;

  let p1 = polygon[0];
  let p2;

  for (let i = 1; i <= numVertices; i++) {
    p2 = polygon[i % numVertices];

    if (y > min(p1.y, p2.y)) {
      if (y <= max(p1.y, p2.y)) {
        if (x <= max(p1.x, p2.x)) {
          const xIntersection = ((y - p1.y) * (p2.x - p1.x)) / (p2.y - p1.y) + p1.x;

          if (p1.x === p2.x || x <= xIntersection) {
            inside = !inside;
          }
        }
      }
    }

    p1 = p2;
  }

  return inside;
}

// adapted from https://en.wikipedia.org/wiki/Gift_wrapping_algorithm#Pseudocode
function convexHull(points) {
	points.sort((p, q) => p.x - q.x);
	let hull = [];
	let i = 0;
	let endPoint;
	let pointOnHull = points[0];
	do {
		hull.push(pointOnHull);
		endPoint = points[0];
		for (let j = 0; j < points.length; j++) {
			let p = p5.Vector.sub(endPoint, pointOnHull);
			let q = p5.Vector.sub(points[j], pointOnHull);
			if (endPoint.equals(pointOnHull) || (p.cross(q)).z < 0) {
				endPoint = points[j];
			}
		}
		i++;
		pointOnHull = endPoint;
	} while (!endPoint.equals(points[0]));
	return hull;
}

function getRoundedPolygon(vertices, r) {
	let roundedPolygon = [];

	if (vertices.length == 2) {
		let v1 = vertices[0];
		let v2 = vertices[1];
		addOffsetSegment(roundedPolygon, v1.x, v1.y, v2.x, v2.y, r);
		addOffsetPoint(roundedPolygon, v1.x, v1.y, v2.x, v2.y, v1.x, v1.y, r);
		addOffsetSegment(roundedPolygon, v2.x, v2.y, v1.x, v1.y, r);
		addOffsetPoint(roundedPolygon, v2.x, v2.y, v1.x, v1.y, v2.x, v2.y, r);
	} else {
		let nVertices = vertices.length;
		let x0 = 0, y0 = 0;
		for (let v of vertices) {
			x0 += v.x;
			y0 += v.y;
		}
		x0 /= nVertices;
		y0 /= nVertices;

		let angleToCenter = (v) => (atan2(v.x-x0, v.y-y0));
		vertices.sort((v1, v2) => (angleToCenter(v1)-angleToCenter(v2)));

		for (let i = 0; i < nVertices; i++) {
			let v1 = vertices[i];
			let v2 = vertices[(i+1)%nVertices];
			let v3 = vertices[(i+2)%nVertices];

			addOffsetSegment(roundedPolygon, v1.x, v1.y, v2.x, v2.y, r);
			addOffsetPoint(roundedPolygon, v1.x, v1.y, v2.x, v2.y, v3.x, v3.y, r);
		}
	}

	return roundedPolygon;
}

function addOffsetSegment(roundedPolygon, x1, y1, x2, y2, r) {
	let dx = x2-x1, dy = y2-y1;
	let magnitude = sqrt(sq(dx)+sq(dy));
	dx = r*dx/magnitude;
	dy = r*dy/magnitude;
	let x1offset = x1-dy;
	let y1offset = y1+dx;
	let x2offset = x2-dy;
	let y2offset = y2+dx;

	roundedPolygon.push(createVector(x1offset, y1offset));
	roundedPolygon.push(createVector(x2offset, y2offset));
}

function addOffsetPoint(roundedPolygon, xA, yA, xB, yB, xC, yC, r) {
	let thetaAB = atan2(yB-yA, xB-xA)+PI/2;
	let thetaBC = atan2(yC-yB, xC-xB)+PI/2;
	if (thetaAB < thetaBC) thetaAB += TAU;

	for (let theta = thetaAB; theta >= thetaBC; theta -= TAU/N_ARCS) {
		let x = xB + r*cos(theta);
		let y = yB + r*sin(theta);
		roundedPolygon.push(createVector(x, y));
	}
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
